// ── Pull the plain request text out of whatever shape the caller sent ────
const input = $input.first().json;
const body  = input.body || {};

const rawText = body.text || body.chatInput || (typeof body === 'string' ? body : JSON.stringify(body));

return [{ json: { raw_text: rawText, received_at: new Date().toISOString() } }];

// ── Safely parse Agent 1's JSON, with a regex fallback if it wasn't clean ─
const agentOut = $input.first().json;
const raw      = $('Extract Raw Message').first().json.raw_text;
const text     = agentOut.output || agentOut.text || '';

let memberId = '';
let channel  = 'email';

try {
  const jsonMatch = text.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    const parsed = JSON.parse(jsonMatch[0]);
    memberId = (parsed.member_id || '').toUpperCase();
    channel  = (parsed.delivery_channel || 'email').toLowerCase();
  }
} catch (e) {
  // fall through to regex fallback below
}

// Fallback net, in case the agent's output wasn't valid JSON
if (!memberId) {
  const m = raw.match(/MBR-[A-Z]+-\d+/i);
  if (m) memberId = m[0].toUpperCase();
}
if (channel !== 'email' && channel !== 'telegram') {
  const lower = raw.toLowerCase();
  channel = (lower.includes('telegram') || lower.includes('chat')) ? 'telegram' : 'email';
}

return [{ json: { member_id: memberId, delivery_channel: channel } }];

// ── Turn raw DynamoDB rows into a clean, plain member profile ───────────
const rows   = $input.all().map(i => i.json);
const intent = $('Parse Extracted Intent').first().json;

const readField = (obj, name) => {
  const v = obj[name];
  if (v && typeof v === 'object') return v.S ?? v.N ?? '';
  return v;
};
const readNum = (obj, name) => parseFloat(readField(obj, name)) || 0;

let member;
if (rows.length === 0) {
  member = { member_id: intent.member_id, found: false };
} else {
  const profile = rows.find(r => readField(r, 'transaction_id') === 'PROFILE') || rows[rows.length - 1];
  member = {
    member_id      : intent.member_id,
    tier           : readField(profile, 'tier') || 'Unknown',
    points_balance : readNum(profile, 'points_balance'),
    points_earned  : readNum(profile, 'points_earned'),
    points_redeemed: readNum(profile, 'points_redeemed'),
    status         : readField(profile, 'status') || 'Unknown',
    member_since   : readField(profile, 'member_since') || 'Unknown',
    tier_expiry    : readField(profile, 'tier_expiry') || 'Unknown',
    found          : true
  };
}

return [{ json: { member, delivery_channel: intent.delivery_channel } }];

const formatted = $input.first().json;
const flat = $('Flatten Member Data').first().json;

const messageText = formatted.output || formatted.text || '';

return [{
  json: {
    formatted_message: messageText,
    subject          : 'Loyalty Status — ' + (flat.member.member_id || 'Unknown Member'),
    delivery_channel : flat.delivery_channel
  }
}];
